package testing

import (
	"testing"
)

func TestAllocsPerRun(t *testing.T) {
	tests := []struct {
		name    string
		runs     int
		expected int
	}{
		{
			name:    "zero runs",
			runs:    0,
			expected: 0,
		},
		{
			name:    "zero allocations",
			runs:    100,
			expected: 0,
		},
		{
			name:    "one allocation",
			runs:    100,
			expected: 1,
		},
		{
			name:    "two allocations",
			runs:    100,
			expected: 2,
		},
		{
			name:    "three allocations",
			runs:    100,
			expected: 3,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := AllocsPerRun(tt.runs, func() { }); got != tt.expected {
				t.Errorf("AllocsPerRun(%d, func()) = %d, want %d", tt.runs, got, tt.expected)
			}
		})
	}
}

